style.css:
@-moz-document domain("character.ai") {
body, .chat-container, .message, .input-container, .header {
        background-color: #ffe4f0 !important;
        color: #4a004e !important;
    }

    .message.bot {
        background-color: #ffd6eb !important;
        color: #4a004e !important;
        border-radius: 15px !important;
    }

    .message.user {
        background-color: #f9c1de !important;
        color: #4a004e !important;
        border-radius: 15px !important;
    }

    .input-container input, .input-container textarea {
        background-color: #fff0f7 !important;
        color: #4a004e !important;
        border: 2px solid #ffadd6 !important;
    }

    .header, .nav-bar {
        background-color: #ffb6d9 !important;
    }

    a, button {
        background-color: #ff99cc !important;
        color: #ffffff !important;
        border-radius: 8px !important;
    }
}
